-- V10 named-grant reads. The runner locks, verifies and backfills existing heads atomically.
ALTER TABLE memplex_source_heads ADD COLUMN read_grants TEXT[] NOT NULL DEFAULT '{}'::text[];

CREATE POLICY memplex_source_heads_source_read_grants ON memplex_source_heads
    FOR SELECT USING ((memplex_source_heads.tenant_id <> '__memplex_legacy__'::text AND memplex_source_heads.tenant_id = current_setting('memplex.tenant_id'::text, true) AND memplex_source_heads.workspace = current_setting('memplex.workspace_id'::text, true) AND memplex_source_heads.visibility = 'user'::text AND memplex_source_heads.state = 'live'::text AND memplex_source_heads.source_class <> 'legacy_unverified'::text AND COALESCE(NULLIF(current_setting('memplex.agent_id'::text, true), ''::text), current_setting('memplex.subject_id'::text, true)) <> ''::text AND COALESCE(NULLIF(current_setting('memplex.agent_id'::text, true), ''::text), current_setting('memplex.subject_id'::text, true)) = ANY (memplex_source_heads.read_grants) AND EXISTS (SELECT 1 FROM memplex_source_authorities grant_authority WHERE (grant_authority.authority_id = memplex_source_heads.authority_id AND grant_authority.tenant_id = memplex_source_heads.tenant_id AND grant_authority.workspace = memplex_source_heads.workspace AND grant_authority.state = 'live'::text AND grant_authority.contract_version = 1))));

CREATE POLICY memplex_derivation_records_source_read_grants ON memplex_derivation_records
    FOR SELECT USING (EXISTS (SELECT 1 FROM memplex_source_heads grant_head WHERE (grant_head.authority_id = memplex_derivation_records.authority_id AND grant_head.kind = 'fact'::text AND grant_head.source_class = 'derived_v1'::text AND grant_head.tenant_id = memplex_derivation_records.tenant_id AND grant_head.owner_subject = memplex_derivation_records.owner_subject AND grant_head.workspace = memplex_derivation_records.workspace AND grant_head.visibility = memplex_derivation_records.visibility AND grant_head.source_agent = memplex_derivation_records.source_agent AND grant_head.source_session = memplex_derivation_records.source_session AND (grant_head.tenant_id <> '__memplex_legacy__'::text AND grant_head.tenant_id = current_setting('memplex.tenant_id'::text, true) AND grant_head.workspace = current_setting('memplex.workspace_id'::text, true) AND grant_head.visibility = 'user'::text AND grant_head.state = 'live'::text AND grant_head.source_class <> 'legacy_unverified'::text AND COALESCE(NULLIF(current_setting('memplex.agent_id'::text, true), ''::text), current_setting('memplex.subject_id'::text, true)) <> ''::text AND COALESCE(NULLIF(current_setting('memplex.agent_id'::text, true), ''::text), current_setting('memplex.subject_id'::text, true)) = ANY (grant_head.read_grants) AND EXISTS (SELECT 1 FROM memplex_source_authorities grant_authority WHERE (grant_authority.authority_id = grant_head.authority_id AND grant_authority.tenant_id = grant_head.tenant_id AND grant_authority.workspace = grant_head.workspace AND grant_authority.state = 'live'::text AND grant_authority.contract_version = 1))) AND ((memplex_derivation_records.record_kind = 'publication'::text AND grant_head.logical_id = memplex_derivation_records.record_key AND (memplex_derivation_records.data ->> 'publication_id'::text) = memplex_derivation_records.record_key) OR (memplex_derivation_records.record_kind = 'target'::text AND grant_head.logical_id = (memplex_derivation_records.data #>> '{token,current_publication}'::text[]) AND (memplex_derivation_records.data ->> 'derivation_key'::text) = memplex_derivation_records.record_key)))));

